module pulse2edge
(
  input [1-1:0] pulse_in,
  input [1-1:0] clk,
  input [1-1:0] grst,
  input [1-1:0] rstb,
  output [1-1:0] edge_out
);

  reg [1-1:0] temp;

  always @(posedge clk) begin
    if(grst | ~rstb) begin
      temp <= 1'b0;
    end else begin
      temp <= edge_out;
    end
  end

  assign edge_out = pulse_in | temp;

endmodule



module pulse2edge_
(
  input [1-1:0] pulse_in,
  input [1-1:0] clk,
  input [1-1:0] grst,
  input [1-1:0] rstb,
  output [1-1:0] edge_out
);

  reg [1-1:0] temp;

  always @(posedge clk) begin
    if(grst | ~rstb) begin
      temp <= 1'b0;
    end else begin
      temp <= edge_out;
    end
  end

  assign edge_out = pulse_in | temp;

endmodule



