module fsm_synapse #
(
  parameter WRES = 3
)
(
  input [1-1:0] input_spike,
  input [WRES-1:0] w_init,
  input [1-1:0] inc,
  input [1-1:0] dec,
  input [1-1:0] clk,
  input [1-1:0] grst,
  input [1-1:0] rstb,
  output [WRES-1:0] w_out,
  output [1-1:0] syn_out
);

  reg [WRES-1:0] weight;
  reg [1-1:0] w_nonzero;

  always @(posedge clk) begin
    if(~rstb) begin
      weight <= w_init;
      w_nonzero <= w_init > 0;
    end else begin
      if(grst) begin
        if((inc == 1'b1) & (weight < 3'b111)) begin
          weight <= weight + 3'b1;
          w_nonzero <= 1'b1;
        end else if((dec == 1'b1) & (weight > 0)) begin
          weight <= weight - 3'b1;
          w_nonzero <= weight[2:1] != 0;
        end else begin
          w_nonzero <= weight > 0;
        end
      end else begin
        if(input_spike) begin
          weight <= weight - 3'b1;
          if(w_nonzero == 1'b0) begin
            w_nonzero <= 1'b0;
          end else if(|weight[2:1] == 0) begin
            w_nonzero <= 1'b0;
          end else begin
            w_nonzero <= 1'b1;
          end
        end 
      end
    end
  end

  assign syn_out = input_spike & w_nonzero;
  assign w_out = weight;

endmodule



module fsm_synapse_ #
(
