  end

  assign syn_out = input_spike & w_nonzero;
  assign w_out = weight;

endmodule



module neuron_body #
(
  parameter INPUT_SIZE = 19,
  parameter THRESHOLD = 6,
  parameter WRES = 3
)
(
  input [19-1:0] acc_in,
  input [1-1:0] clk,
  input [1-1:0] grst,
  input [1-1:0] rstb,
  output [1-1:0] output_spike
);

  wire [1-1:0] edge_spike;
  wire [1-1:0] pulse_spike;

  pac
  #(
    .INP(19),
    .THRESHOLD(6)
  )
  acc
  (
    .in(acc_in),
    .clk(clk),
    .grst(grst),
    .rstb(rstb),
    .pac_out(edge_spike)
  );


  edge2pulse
  epn
  (
    .edge_in(edge_spike),
    .clk(clk),
    .pulse_out(pulse_spike)
  );


  fsm_convert
  #(
    .WRES(3)
  )
  conv
  (
    .in(pulse_spike),
    .clk(clk),
    .rstb(rstb),
    .out(output_spike)
  );


endmodule



module pac #
(
  parameter INP = 19,
  parameter THRESHOLD = 6
)
