    .rstb(rstb),
    .out(inhibit_spikes[7])
  );

  assign li_out[0] = inhibit_spikes[0];
  assign li_out[1] = inhibit_spikes[1] & ~(|inhibit_spikes[0:0]);
  assign li_out[2] = inhibit_spikes[2] & ~(|inhibit_spikes[1:0]);
  assign li_out[3] = inhibit_spikes[3] & ~(|inhibit_spikes[2:0]);
  assign li_out[4] = inhibit_spikes[4] & ~(|inhibit_spikes[3:0]);
  assign li_out[5] = inhibit_spikes[5] & ~(|inhibit_spikes[4:0]);
  assign li_out[6] = inhibit_spikes[6] & ~(|inhibit_spikes[5:0]);
  assign li_out[7] = inhibit_spikes[7] & ~(|inhibit_spikes[6:0]);

