module less_equal
(
  input [1-1:0] data_in,
  input [1-1:0] inhibit_in,
  input [1-1:0] clk,
  input [1-1:0] grst,
  input [1-1:0] rstb,
  output [1-1:0] out
);

  wire [1-1:0] inhibit_only;
  wire [1-1:0] inhibit_only_edge;
  assign inhibit_only = ~data_in & inhibit_in;

  pulse2edge
  pe_le
  (
    .pulse_in(inhibit_only),
    .clk(clk),
    .grst(grst),
    .rstb(rstb),
    .edge_out(inhibit_only_edge)
  );

  assign out = data_in & ~inhibit_only_edge;

endmodule



module stdp #
(
  parameter WRES = 3
)
(
  input [WRES-1:0] weight_in,
  input [1-1:0] ein,
  input [1-1:0] eout,
  input [1-1:0] capture_brv,
  input [1-1:0] minus_brv,
  input [1-1:0] search_brv,
  input [1-1:0] backoff_brv,
  input [1-1:0] min_brv,
  input [6-1:0] F_brv,
  input [1-1:0] clk,
  input [1-1:0] grst,
  input [1-1:0] rstb,
  output [1-1:0] inc,
  output [1-1:0] dec
);

  wire [4-1:0] stdp_cases;
  wire [1-1:0] fout_brv;

  stdp_case_gen
  casegen
  (
    .ein(ein),
    .eout(eout),
    .clk(clk),
    .grst(grst),
    .rstb(rstb),
    .stdp_cases(stdp_cases)
  );


  stabilize_func
  #(
    .WRES(3)
  )
  flogic
  (
    .weight(weight_in),
    .F_brv(F_brv),
    .out(fout_brv)
  );


  incdec
  control
  (
    .stdp_cases(stdp_cases),
    .capture_brv(capture_brv),
    .minus_brv(minus_brv),
    .search_brv(search_brv),
    .backoff_brv(backoff_brv),
    .min_brv(min_brv),
    .fout_brv(fout_brv),
    .inc(inc),
    .dec(dec)
  );


endmodule



module stdp_case_gen
(
  input [1-1:0] ein,
  input [1-1:0] eout,
  input [1-1:0] clk,
  input [1-1:0] grst,
  input [1-1:0] rstb,
  output [4-1:0] stdp_cases
);

  wire [1-1:0] eout_only;
  wire [1-1:0] e_both;
  wire [1-1:0] e_one;
  wire [1-1:0] greater;
  assign eout_only = ~ein & eout;

  pulse2edge
  pe
  (
    .pulse_in(eout_only),
    .clk(clk),
    .grst(grst),
    .rstb(rstb),
    .edge_out(greater)
  );

  assign e_both = ein & eout;
  assign e_one = ein ^ eout;
  assign stdp_cases[0] = ~greater & e_both;
  assign stdp_cases[1] = greater & e_both;
  assign stdp_cases[2] = ~greater & e_one;
  assign stdp_cases[3] = greater & e_one;

endmodule



module stabilize_func #
(
  parameter WRES = 3
)
(
  input [WRES-1:0] weight,
  input [6-1:0] F_brv,
  output [1-1:0] out
);


      always @*
      begin
          out = 0;
          if ((weight == 0) | (weight == ((1<<WRES)-1))) out = 0;
          for (int i = 1; i < ((1<<WRES)-1); i++)
          begin
              if (weight == i) out = F_brv[i-1];
          end
      end

endmodule



module incdec
(
  input [4-1:0] stdp_cases,
  input [1-1:0] capture_brv,
  input [1-1:0] minus_brv,
  input [1-1:0] search_brv,
  input [1-1:0] backoff_brv,
  input [1-1:0] min_brv,
  input [1-1:0] fout_brv,
  output [1-1:0] inc,
  output [1-1:0] dec
);

  wire [1-1:0] stabilize_brv;
  assign stabilize_brv = fout_brv | min_brv;
  assign inc = stdp_cases[0] & capture_brv & stabilize_brv | stdp_cases[2] & search_brv;
  assign dec = stdp_cases[1] & minus_brv & stabilize_brv | stdp_cases[3] & backoff_brv & stabilize_brv;

endmodule



